const LABELS={title:['Choose Your Path','আপনার পথ বাছাই'],vehicle:['Choose Your Vehicle','বাহন বেছে নিন'],stall:['Choose Your Stall','স্টল বেছে নিন'],back:['Back','ফিরে যান'],pickVehicle:['Select a vehicle to begin.','শুরু করতে বাহন বেছে নিন।'],pickStall:['Select a stall to begin.','শুরু করতে দোকান বেছে নিন।']};
const VEHICLE_ICON='<svg viewBox="0 0 48 48" xmlns="http://www.w3.org/2000/svg" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M8 12h32v16H8z"/><circle cx="16" cy="30" r="4"/><circle cx="32" cy="30" r="4"/></svg>';
const STALL_ICON='<svg viewBox="0 0 48 48" xmlns="http://www.w3.org/2000/svg" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M6 36h36L40 14H8z"/><path d="M14 14V8h20v6"/></svg>';
export function createMainMenu({lang,setLang,vehicles,stalls,launchVehicle,launchStall}){
 const L=lang,t=k=>LABELS[k][L()==='bn'?1:0],root=document.createElement('div');root.id='main-menu';root.className='hidden';root.setAttribute('aria-hidden','true');root.tabIndex=-1;document.body.append(root);let active=false;
 function build(){root.innerHTML=`<button type="button" class="mm-close" aria-label="Close menu">×</button><button type="button" class="mm-lang" aria-label="Language"><span class="lang-sel ${L()==='en'?'selected':''}" data-lang="en">EN</span><span class="lang-sel ${L()==='bn'?'selected':''}" data-lang="bn">বাংলা</span></button><div class="mm-content"><div class="mm-viewport"><section class="mm-screen" data-screen="main"><div class="mm-head"><span class="mm-eyebrow">DHAKA TERROR · POV BANGLADESH</span><h2 class="mm-title">${t('title')}</h2></div><div class="mm-options"><button type="button" class="mm-option" data-target="vehicle"><span class="mm-option-icon">${VEHICLE_ICON}</span><span class="mm-option-label">${t('vehicle')}</span></button><button type="button" class="mm-option" data-target="stall"><span class="mm-option-icon">${STALL_ICON}</span><span class="mm-option-label">${t('stall')}</span></button></div></section><section class="mm-screen" data-screen="vehicle" hidden><button type="button" class="mm-back">← ${t('back')}</button><div class="mm-head"><h3 class="mm-title">${t('vehicle')}</h3><p class="mm-subtitle">${t('pickVehicle')}</p></div><div class="mm-grid">${vehicles.map(v=>`<button type="button" class="mm-card" data-vehicle="${v.id}"><span class="mm-card-art" style="--card:${v.color}"><img src="${v.img}" class="mm-card-img" alt=""></span><span class="mm-card-name">${v.name[L()==='bn'?1:0]}</span><span class="mm-card-sub">${v.sub[L()==='bn'?1:0]}</span></button>`).join('')}</div></section><section class="mm-screen" data-screen="stall" hidden><button type="button" class="mm-back">← ${t('back')}</button><div class="mm-head"><h3 class="mm-title">${t('stall')}</h3><p class="mm-subtitle">${t('pickStall')}</p></div><div class="mm-grid">${stalls.map(s=>`<button type="button" class="mm-card" data-stall="${s.variant}"><span class="mm-card-art" style="--card:${s.color}"><img src="${s.img}" class="mm-card-img" alt=""></span><span class="mm-card-name">${s.name[L()==='bn'?1:0]}</span></button>`).join('')}</div></section></div></div>`;
 root.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>show(b.dataset.target));root.querySelectorAll('[data-vehicle]').forEach(b=>b.onclick=()=>{hide();launchVehicle(b.dataset.vehicle)});root.querySelectorAll('[data-stall]').forEach(b=>b.onclick=()=>{hide();launchStall(Number(b.dataset.stall))});root.querySelectorAll('.mm-back').forEach(b=>b.onclick=()=>show('main'));root.querySelector('.mm-close').onclick=hide;root.querySelectorAll('.lang-sel').forEach(b=>b.onclick=()=>setLang(b.dataset.lang));
 }
 function show(screen){root.setAttribute('data-screen',screen);root.querySelectorAll('[data-screen]').forEach(s=>s.hidden=s.dataset.screen!==screen)}function hide(){root.classList.add('hidden');root.setAttribute('aria-hidden','true');active=false}function showMenu(){if(!root.parentNode)document.body.append(root);root.classList.remove('hidden');root.setAttribute('aria-hidden','false');active=true;build();show('main')}
 return{show:showMenu,hide,relang:()=>{build()},get active(){return active}};
}
